  const h2 = fnv1a(key, 0x01000193).toString(16).padStart(8, '0');
  return 'dup-' + h1 + h2;
}

function pickPrimary(members) {
  const ts = (d) => {
    const t = d ? Date.parse(d) : NaN;
    return Number.isFinite(t) ? t : Infinity;
  };
