const ALLOWED_ACCOUNT_TYPES = ['SANDBOX', 'DEVELOPER_TEST'];
const NOTIFY_TARGET_VALUES = ['slack', 'notion', 'none'];
const SECRET_ENV_KEYS = ['HUBSPOT_ACCESS_TOKEN', 'SLACK_WEBHOOK_URL', 'NOTION_API_KEY', 'NOTION_DATABASE_ID'];
